=== FILE: skid_buffer.v ===
// skid_buffer: valid/ready register slice with a skid register.
// Implements microarchitecture.md (state table section 2, next-state section 3)
// for the interface in interface_spec.md. Every output comes from a flop.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat moves on this edge.
    wire s_fire = s_valid && !skid_valid;

    // Inverter after a flop: no combinational path from any input.
    assign s_ready = !skid_valid;

    // Control: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else if (m_free) begin
            if (skid_valid) begin
                // Skid beat moves to the output register.
                m_valid    <= 1'b1;
                skid_valid <= 1'b0;
            end else begin
                // Output register takes the input beat, if any.
                m_valid    <= s_valid;
            end
        end else if (s_fire) begin
            // Output stalled: catch the beat in the skid register.
            skid_valid <= 1'b1;
        end
    end

    // Data: not reset; each register loads only in its control's row.
    always @(posedge clk) begin
        if (m_free) begin
            m_data <= skid_valid ? skid_data : s_data;
        end
        if (!m_free && s_fire) begin
            skid_data <= s_data;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (partial; not the full queue proof).
    reg f_past_valid = 1'b0;
    reg f_reset_seen = 1'b0;

    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n) begin
            f_reset_seen <= 1'b1;
        end
    end

    always @(posedge clk) begin
        // Reset drops every held beat.
        if (f_past_valid && !$past(rst_n)) begin
            assert (!m_valid);
            assert (!skid_valid);
        end
        // The skid register is only full while the output register is full.
        if (f_reset_seen) begin
            assert (!skid_valid || m_valid);
        end
        // Hold: a beat offered and not taken stays, with the same data.
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready)) begin
            assert (m_valid);
            assert (m_data == $past(m_data));
        end
        // The skid beat holds while the output stalls.
        if (f_past_valid && $past(f_reset_seen) && $past(rst_n)
                && $past(skid_valid) && !$past(m_ready)) begin
            assert (skid_valid);
            assert (skid_data == $past(skid_data));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===

