// skid_buffer_tb: self-checking testbench for skid_buffer.
// Lanes at WIDTH 8 and WIDTH 1 share the same handshake stimulus.
// A two-entry queue model is checked against the outputs every cycle.
`timescale 1ns/1ps

module skid_buffer_tb;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data;

    wire       s_ready;
    wire       m_valid;
    wire [7:0] m_data;

    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready),
        .s_data  (s_data),
        .m_valid (m_valid),
        .m_ready (m_ready),
        .m_data  (m_data)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    // Model state
    integer    cnt;
    reg  [7:0] q0;
    reg  [7:0] q1;
    integer    sent;
    integer    recv;
    integer    dropped;
    reg        prev_stall;
    reg  [7:0] prev_data;

    integer    passed;
    integer    failed;
    integer    i;
    integer    mode;
    reg [31:0] r;
    reg [8*64-1:0] nonce;

    task check;
        input            cond;
        input [8*64-1:0] what;
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check failed at %0t: %0s", $time, what);
            end
        end
    endtask

    task check_outputs;
        begin
            check(m_valid === (cnt > 0), "m_valid matches beats held");
            check(s_ready === (cnt < 2), "s_ready matches beats held");
            if (cnt > 0) begin
                check(m_data === q0, "m_data is the oldest beat");
            end
            check(m_valid1 === m_valid, "w1: m_valid matches w8");
            check(s_ready1 === s_ready, "w1: s_ready matches w8");
            if (cnt > 0) begin
                check(m_data1 === q0[0:0], "w1: m_data is the oldest beat");
            end
            if (prev_stall) begin
                check(m_valid === 1'b1, "hold: stalled beat still offered");
                check(m_data === prev_data, "hold: stalled beat unchanged");
            end
        end
    endtask

    // Called just after a rising edge with the next inputs set.
    // Checks outputs, wiggles inputs to prove s_ready is registered, then
    // samples the handshakes, waits for the edge, and updates the model.
    reg       t_sr;
    reg       t_sr1;
    reg       t_mv;
    reg [7:0] t_md;
    reg       t_up;
    reg       t_dn;
    reg       t_rs;
    reg [7:0] t_din;

    task tick;
        begin
            check_outputs;

            t_sr  = s_ready;
            t_sr1 = s_ready1;
            t_mv  = m_valid;
            t_md  = m_data;
            s_valid = ~s_valid;
            m_ready = ~m_ready;
            s_data  = ~s_data;
            #1;
            check(s_ready === t_sr, "s_ready ignores inputs in cycle");
            check(s_ready1 === t_sr1, "w1: s_ready ignores inputs");
            check(m_valid === t_mv, "m_valid ignores inputs in cycle");
            check(m_data === t_md, "m_data ignores inputs in cycle");
            s_valid = ~s_valid;
            m_ready = ~m_ready;
            s_data  = ~s_data;
            #1;

            t_up  = s_valid && s_ready;
            t_dn  = m_valid && m_ready;
            t_rs  = rst_n;
            t_din = s_data;
            prev_stall = t_rs && m_valid && !m_ready;
            prev_data  = m_data;

            @(posedge clk);

            if (!t_rs) begin
                dropped = dropped + cnt;
                cnt = 0;
            end else begin
                if (t_dn && (cnt > 0)) begin
                    recv = recv + 1;
                    q0   = q1;
                    cnt  = cnt - 1;
                end
                if (t_up && (cnt < 2)) begin
                    if (cnt == 0) begin
                        q0 = t_din;
                    end else begin
                        q1 = t_din;
                    end
                    cnt  = cnt + 1;
                    sent = sent + 1;
                end
            end
            #1;
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        cnt = 0;
        sent = 0;
        recv = 0;
        dropped = 0;
        prev_stall = 1'b0;
        prev_data = 8'h00;
        q0 = 8'h00;
        q1 = 8'h00;
        rst_n = 1'b0;
        s_valid = 1'b0;
        m_ready = 1'b0;
        s_data = 8'h00;

        // Bring both lanes into reset before checking anything.
        @(posedge clk);
        @(posedge clk);
        #1;

        // 1. Reset values
        tick;
        tick;
        check(m_valid === 1'b0, "reset: m_valid low");
        check(s_ready === 1'b1, "reset: s_ready high");
        check(m_valid1 === 1'b0 && s_ready1 === 1'b1, "reset: w1 values");
        rst_n = 1'b1;
        tick;
        check(m_valid === 1'b0 && s_ready === 1'b1, "idle after reset");

        // 2. One-cycle latency
        s_valid = 1'b1;
        s_data  = 8'hA5;
        m_ready = 1'b1;
        check(m_valid === 1'b0, "latency: nothing offered yet");
        tick;
        check(m_valid === 1'b1 && m_data === 8'hA5, "latency: offered after accept");
        s_valid = 1'b0;
        tick;
        check(m_valid === 1'b0, "latency: beat left");

        // 3. Full throughput
        m_ready = 1'b1;
        s_valid = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            s_data = i[7:0];
            check(s_ready === 1'b1, "throughput: s_ready high");
            if (i > 0) begin
                check(m_valid === 1'b1, "throughput: no bubble");
                check(m_data === (i[7:0] - 8'd1), "throughput: data in order");
            end
            tick;
        end
        s_valid = 1'b0;
        tick;
        tick;
        check(m_valid === 1'b0, "throughput: drained");

        // 4. Stall with one beat held, then two; release with no bubble
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h11;
        check(s_ready === 1'b1, "stall: empty slice ready");
        tick;
        check(m_valid === 1'b1 && m_data === 8'h11, "stall: first beat offered");
        check(s_ready === 1'b1, "stall: one held, still ready");
        s_data = 8'h22;
        tick;
        check(s_ready === 1'b0, "stall: two held, s_ready low");
        check(m_data === 8'h11, "stall: oldest still offered");
        s_data = 8'h33;
        tick;
        tick;
        check(s_ready === 1'b0, "stall: third beat refused");
        check(m_valid === 1'b1 && m_data === 8'h11, "stall: full slice holds");
        s_data = 8'h44;
        tick;
        s_data = 8'h33;
        m_ready = 1'b1;
        tick;
        check(m_valid === 1'b1 && m_data === 8'h22, "release: second beat next");
        check(s_ready === 1'b1, "release: s_ready rises");
        tick;
        check(m_valid === 1'b1 && m_data === 8'h33, "release: third beat no bubble");
        s_valid = 1'b0;
        tick;
        check(m_valid === 1'b0, "release: drained");
        check(sent == recv + dropped, "release: every beat out once");

        // 5. Random traffic against the model
        for (i = 0; i < 3000; i = i + 1) begin
            r = $random;
            mode = (i / 500) % 3;
            if (mode == 0) begin
                s_valid = r[0] | r[1];
                m_ready = r[2] & r[3];
            end else if (mode == 1) begin
                s_valid = r[0] & r[1];
                m_ready = r[2] | r[3];
            end else begin
                s_valid = r[0];
                m_ready = r[2];
            end
            s_data = r[15:8];
            tick;
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        tick;
        tick;
        tick;
        tick;
        check(cnt == 0, "random: model drained");
        check(m_valid === 1'b0 && s_ready === 1'b1, "random: slice drained");
        check(sent == recv + dropped, "random: every beat out once");

        // 6. Reset with beats held
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h5A;
        tick;
        s_data  = 8'hC3;
        tick;
        check(m_valid === 1'b1 && s_ready === 1'b0, "reset: two beats held");
        rst_n = 1'b0;
        tick;
        check(m_valid === 1'b0 && s_ready === 1'b1, "reset drops held beats");
        check(m_valid1 === 1'b0 && s_ready1 === 1'b1, "w1: reset drops held beats");
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        tick;
        tick;
        check(m_valid === 1'b0, "reset: no stale beat after");
        s_valid = 1'b1;
        s_data  = 8'h77;
        tick;
        s_valid = 1'b0;
        check(m_valid === 1'b1 && m_data === 8'h77, "reset: beat after reset");
        tick;
        tick;
        check(m_valid === 1'b0, "reset: final drain");
        check(sent == recv + dropped, "final: every beat out once");

        // Verdict
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) begin
            nonce = "none";
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
